PYTHON="$(cat graphify-out/.graphify_python)" && "$PYTHON" - <<'PY'
import json
from pathlib import Path
x=json.loads(Path('graphify-out/.graphify_extract.json').read_text(encoding='utf-8'))
ids={n['id'] for n in x['nodes']}
for i,e in enumerate(x['edges']):
    if e.get('source') not in ids or e.get('target') not in ids:
        print(i, e.get('source'), '->', e.get('target'), e.get('relation'), e.get('source_file'))
print('self loops:')
for e in x['edges']:
    if e.get('source') == e.get('target'):
        print(e.get('source'), e.get('relation'), e.get('source_file'))
PY

