PYTHON="$(cat graphify-out/.graphify_python)" && "$PYTHON" - <<'PY'
import inspect, json
from pathlib import Path
from graphify.cli import _stamped_manifest_files
from graphify.detect import _stat_and_hash
for obj in (_stamped_manifest_files, _stat_and_hash):
 print('\n--',obj.__name__,'--')
 for i,line in enumerate(inspect.getsource(obj).splitlines(),1): print(f'{i:3} {line}')
ex=json.loads(Path('graphify-out/.graphify_extract.json').read_text(encoding='utf-8'))
for n in ex['nodes']:
 if n.get('source_file','').endswith('.pdf'):
  print('PDF node:',n.get('source_file'),n.get('_origin'),n.get('file_type'))
PY

